        original: 69.99,
        sale: 44.99,
        discount: 36,
        description: 'Elegant marble organizer for your workspace',
        timer: '3 days remaining'
    }
];

const editorialContent = [
    {
        id: 201,
        title: 'How to Master Minimalist Interior Design',
        tag: 'Design Tips',
        excerpt: 'Learn the principles of minimalism and transform your living space into a serene, organized sanctuary.',
        emoji: '✨'
    },
    {
        id: 202,
        title: 'Sustainable Home Decor: Making Ethical Choices',
        tag: 'Sustainability',
        excerpt: 'Discover eco-friendly alternatives and how choosing sustainable products helps the environment.',
        emoji: '🌱'
    },
    {
        id: 203,
        title: 'The Perfect Home Office Setup',
        tag: 'Work From Home',
        excerpt: 'Essential furniture and decor items to create a productive and comfortable workspace at home.',
        emoji: '💻'
    }
];

// Shopping Cart
let cart = [];

// Initialize page
document.addEventListener('DOMContentLoaded', () => {
    renderFeaturedProducts();
    renderDealProducts();
    renderEditorialContent();
    setupEventListeners();
    loadCartFromStorage();
});

// Render Featured Products
function renderFeaturedProducts() {
    const container = document.getElementById('featuredProducts');
    container.innerHTML = featuredProducts.map(product => `
        <div class="product-card">
            <div class="product-image">${product.emoji}</div>
            <div class="product-info">
                <span class="product-category">${product.category}</span>
                <h3 class="product-name">${product.name}</h3>
                <p class="product-description">${product.description}</p>
                <div class="product-footer">
                    <span class="product-price">$${product.price.toFixed(2)}</span>
                    <button class="add-to-cart-btn" onclick="addToCart(${product.id}, '${product.name}', ${product.price})">Add</button>
                </div>
            </div>
        </div>
    `).join('');
}

// Render Deal Products
function renderDealProducts() {
    const container = document.getElementById('dealsProducts');
    container.innerHTML = dealProducts.map(product => `
        <div class="deal-card">
            <span class="deal-badge">${product.discount}% OFF</span>
            <div class="deal-content">
                <h3>${product.name}</h3>
                <p class="deal-description">${product.description}</p>
                <div class="deal-price-section">
                    <span class="deal-price-original">$${product.original.toFixed(2)}</span>
                    <span class="deal-price">$${product.sale.toFixed(2)}</span>
                </div>
                <p class="deal-timer">⏱️ ${product.timer}</p>
            </div>
            <button class="btn btn-primary" style="align-self: flex-start; margin-top: auto;" onclick="addToCart(${product.id}, '${product.name}', ${product.sale})">Shop Deal</button>
        </div>
    `).join('');
}

// Render Editorial Content
function renderEditorialContent() {
    const container = document.getElementById('editorialContent');
    container.innerHTML = editorialContent.map(article => `
        <div class="editorial-card">
            <div class="editorial-image">${article.emoji}</div>
            <div class="editorial-content">
                <span class="editorial-tag">${article.tag}</span>
                <h3 class="editorial-title">${article.title}</h3>
                <p class="editorial-excerpt">${article.excerpt}</p>
                <a href="#" class="read-more">Read Story →</a>
            </div>
        </div>
    `).join('');
}

// Add to Cart
function addToCart(id, name, price) {
    const existingItem = cart.find(item => item.id === id);

    if (existingItem) {
        existingItem.quantity += 1;
    } else {
        cart.push({
            id,
            name,
            price,
            quantity: 1
        });
    }

    updateCartUI();
    saveCartToStorage();
    showCartNotification();
}

// Update Cart UI
function updateCartUI() {
    const cartCount = document.getElementById('cartCount');
    const totalItems = cart.reduce((sum, item) => sum + item.quantity, 0);

    if (totalItems > 0) {
        cartCount.textContent = totalItems;
        cartCount.classList.add('show');
    } else {
        cartCount.classList.remove('show');
    }
}

// Show Cart Notification
function showCartNotification() {
    const notification = document.createElement('div');
    notification.style.cssText = `
        position: fixed;
        bottom: 20px;
        right: 20px;
        background-color: var(--success-color);
        color: white;
        padding: 1rem 1.5rem;
        border-radius: 4px;
        z-index: 999;
        animation: slideIn 0.3s ease;
        font-weight: 500;
    `;
    notification.textContent = '✓ Added to cart';

    document.body.appendChild(notification);

    setTimeout(() => {
        notification.style.animation = 'slideOut 0.3s ease';
        setTimeout(() => notification.remove(), 300);
    }, 2000);
}

// Open Cart Modal
function openCart() {
    const modal = document.getElementById('cartModal');
    modal.classList.add('show');
    renderCartItems();
}

// Close Cart Modal
function closeCart() {
    document.getElementById('cartModal').classList.remove('show');
}

// Render Cart Items
function renderCartItems() {
    const cartItemsContainer = document.getElementById('cartItems');

    if (cart.length === 0) {
        cartItemsContainer.innerHTML = '<p class="empty-cart">Your cart is empty</p>';
        return;
    }

    const total = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);

    cartItemsContainer.innerHTML = `
        ${cart.map((item, index) => `
            <div class="cart-item">
                <div class="cart-item-info">
                    <div class="cart-item-name">${item.name}</div>
                    <div style="color: var(--light-text); font-size: 0.9rem;">Qty: ${item.quantity}</div>
                </div>
                <div style="text-align: right;">
                    <div class="cart-item-price">$${(item.price * item.quantity).toFixed(2)}</div>
                    <button class="remove-from-cart" onclick="removeFromCart(${index})">Remove</button>
                </div>
            </div>
        `).join('')}
        <div style="border-top: 2px solid var(--border-color); padding-top: 1rem; margin-top: 1rem;">
            <div style="display: flex; justify-content: space-between; font-size: 1.2rem; font-weight: 600; color: var(--text-color);">
                <span>Total:</span>
                <span>$${total.toFixed(2)}</span>
            </div>
        </div>
    `;
}

// Remove from Cart
function removeFromCart(index) {
    cart.splice(index, 1);
    updateCartUI();
    renderCartItems();
    saveCartToStorage();
}

// Checkout
function checkout() {
    if (cart.length === 0) {
        alert('Your cart is empty!');
        return;
    }

    const total = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);
    alert(`Proceeding to checkout!\n\nTotal: $${total.toFixed(2)}\n\nThank you for shopping with ModernShop!`);
    cart = [];
    updateCartUI();
    closeCart();
    saveCartToStorage();
}

// Newsletter Submit
function handleNewsletterSubmit(event) {
    event.preventDefault();
    const email = event.target.querySelector('input[type="email"]').value;
    alert(`Welcome! You've been subscribed with ${email}`);
    event.target.reset();
}

// Setup Event Listeners
function setupEventListeners() {
    document.querySelector('.cart-btn').addEventListener('click', openCart);

    // Close modal when clicking outside
    document.getElementById('cartModal').addEventListener('click', (e) => {
        if (e.target.id === 'cartModal') {
            closeCart();
        }
    });

    // Close modal with Escape key
    document.addEventListener('keydown', (e) => {
        if (e.key === 'Escape') {
            closeCart();
        }
    });
}

// Local Storage Management
function saveCartToStorage() {
    localStorage.setItem('modernshop_cart', JSON.stringify(cart));
}

function loadCartFromStorage() {
    const saved = localStorage.getItem('modernshop_cart');
    if (saved) {
        cart = JSON.parse(saved);
        updateCartUI();
    }
}

// Add CSS animation styles
const style = document.createElement('style');
style.textContent = `
    @keyframes slideIn {
        from {
            transform: translateX(400px);
            opacity: 0;
        }
        to {
            transform: translateX(0);
            opacity: 1;
        }
    }

    @keyframes slideOut {
        from {
            transform: translateX(0);
            opacity: 1;
        }
        to {
            transform: translateX(400px);
            opacity: 0;
        }
    }
`;
document.head.appendChild(style);

