            </div>
            <button class="btn btn-primary" style="align-self: flex-start; margin-top: auto;" onclick="addToCart(${product.id}, '${product.name}', ${product.sale})">Shop Deal</button>
        </div>
    `).join('');
}

// Render Editorial Content
function renderEditorialContent() {
    const container = document.getElementById('editorialContent');
    container.innerHTML = editorialContent.map(article => `
        <div class="editorial-card">
            <div class="editorial-image">${article.emoji}</div>
            <div class="editorial-content">
                <span class="editorial-tag">${article.tag}</span>
                <h3 class="editorial-title">${article.title}</h3>
                <p class="editorial-excerpt">${article.excerpt}</p>
                <a href="#" class="read-more">Read Story →</a>
            </div>
        </div>
    `).join('');
}

// Add to Cart
function addToCart(id, name, price) {
    const existingItem = cart.find(item => item.id === id);

    if (existingItem) {
        existingItem.quantity += 1;
    } else {
        cart.push({
            id,
            name,
            price,
            quantity: 1
        });
    }

    updateCartUI();
    saveCartToStorage();
    showCartNotification();
}

// Update Cart UI
function updateCartUI() {
    const cartCount = document.getElementById('cartCount');
    const totalItems = cart.reduce((sum, item) => sum + item.quantity, 0);

    if (totalItems > 0) {
        cartCount.textContent = totalItems;
        cartCount.classList.add('show');
    } else {
        cartCount.classList.remove('show');
    }
}

// Show Cart Notification
function showCartNotification() {
    const notification = document.createElement('div');
    notification.style.cssText = `
        position: fixed;
        bottom: 20px;
        right: 20px;
        background-color: var(--success-color);
        color: white;
        padding: 1rem 1.5rem;
        border-radius: 4px;
        z-index: 999;
        animation: slideIn 0.3s ease;
        font-weight: 500;
    `;
    notification.textContent = '✓ Added to cart';

    document.body.appendChild(notification);

    setTimeout(() => {
        notification.style.animation = 'slideOut 0.3s ease';
        setTimeout(() => notification.remove(), 300);
    }, 2000);
}

// Open Cart Modal
function openCart() {
    const modal = document.getElementById('cartModal');
    modal.classList.add('show');
    renderCartItems();
}

// Close Cart Modal
function closeCart() {
    document.getElementById('cartModal').classList.remove('show');
}

// Render Cart Items
function renderCartItems() {
    const cartItemsContainer = document.getElementById('cartItems');

    if (cart.length === 0) {
        cartItemsContainer.innerHTML = '<p class="empty-cart">Your cart is empty</p>';
        return;
    }

    const total = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);

    cartItemsContainer.innerHTML = `
        ${cart.map((item, index) => `
            <div class="cart-item">
                <div class="cart-item-info">
                    <div class="cart-item-name">${item.name}</div>
                    <div style="color: var(--light-text); font-size: 0.9rem;">Qty: ${item.quantity}</div>
                </div>
                <div style="text-align: right;">
                    <div class="cart-item-price">$${(item.price * item.quantity).toFixed(2)}</div>
                    <button class="remove-from-cart" onclick="removeFromCart(${index})">Remove</button>
                </div>
            </div>
        `).join('')}
        <div style="border-top: 2px solid var(--border-color); padding-top: 1rem; margin-top: 1rem;">
            <div style="display: flex; justify-content: space-between; font-size: 1.2rem; font-weight: 600; color: var(--text-color);">
                <span>Total:</span>
                <span>$${total.toFixed(2)}</span>
            </div>
        </div>
    `;
}

// Remove from Cart
function removeFromCart(index) {
    cart.splice(index, 1);
    updateCartUI();
    renderCartItems();
    saveCartToStorage();
}

// Checkout
function checkout() {
    if (cart.length === 0) {
        alert('Your cart is empty!');
        return;
    }

    const total = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);
    alert(`Proceeding to checkout!\n\nTotal: $${total.toFixed(2)}\n\nThank you for shopping with ModernShop!`);
    cart = [];
    updateCartUI();
    closeCart();
    saveCartToStorage();
}

// Newsletter Submit
function handleNewsletterSubmit(event) {
    event.preventDefault();
    const email = event.target.querySelector('input[type="email"]').value;
    alert(`Welcome! You've been subscribed with ${email}`);
    event.target.reset();
}

// Setup Event Listeners
function setupEventListeners() {
    document.querySelector('.cart-btn').addEventListener('click', openCart);

